#!/usr/bin/env Rscript
# m_e1: extraction for the molecular and neuroimaging module. Extracts, renames and writes columns only;
# no cleaning or derivation.
#
# Groups and field IDs are in config_molecular.yaml (extract.groups); the brain GMV / FA list is read from
# molecular/ref/brain_features.csv (generated by py/build_brain_ref.py). A group can list fields in any mix of:
#   fields: {field_id: short_name}   explicit; fields absent from the main table go to m_e1_missing.csv
#   list:   CSV under molecular/ref/  columns field / short_name / label / modality
#   ranges: [[a, b], ...]            field ID ranges (NMR); IDs absent from the table are not counted as missing
#   companions:                      per-assay companion fields = field ID + offset (missing reason / reportability)
# Group options:
#   gate: true / false               true = imaging cohort only (field 53 present at gate_instances)
#   instances: all | [0, 2]
#   naming: short (default) -> {short}_i{instance}[_a{array}]; rap -> p{field}_i{instance}_a{array} (for ukbnmr)
#   drop_empty_rows: true            keep only participants with at least one non-missing value in the group
#
# Outputs (<paths.out>/extract/): m_e1_{group}.csv.gz, m_e1_dictionary.csv, m_e1_missing.csv,
# m_e1_availability.csv. With --groups, the three summary files are updated for those groups only.
#
#   Rscript molecular/R/m_e1_extract.R
#   Rscript molecular/R/m_e1_extract.R --groups blood_bc,cov_extra
#   Rscript molecular/R/m_e1_extract.R --main a.csv,b.tab --out results/molecular --withdraw w.csv

suppressPackageStartupMessages({
  library(data.table)
  library(yaml)
})
say <- function(...) cat(sprintf(...), "\n", sep = "")
warn <- function(...) say("  [WARN] %s", sprintf(...))
die <- function(...) { say("  [FAIL] %s", sprintf(...)); quit(status = 1) }
t_start <- Sys.time()
elapsed <- function() sprintf("%.1f min", as.numeric(difftime(Sys.time(), t_start, units = "mins")))
`%||%` <- function(a, b) if (is.null(a)) b else a

here <- tryCatch(dirname(normalizePath(sub("^--file=", "", grep("^--file=",
  commandArgs(trailingOnly = FALSE), value = TRUE)[1]))), error = function(e) ".")
root <- normalizePath(file.path(here, "..", ".."), mustWork = FALSE)     # repository root
from_root <- function(p) if (grepl("^(/|[A-Za-z]:)", p)) p else file.path(root, p)
cfg <- read_yaml(file.path(here, "..", "config_molecular.yaml"))

args <- commandArgs(trailingOnly = TRUE)
opt <- function(name, default = NULL) {
  i <- match(paste0("--", name), args)
  if (is.na(i)) return(default)
  if (i == length(args) || startsWith(args[i + 1], "--")) return(TRUE)
  args[i + 1]
}

# ── Paths ─────────────────────────────────────────────────────────────
main_files <- opt("main")
main_files <- if (is.null(main_files)) from_root(cfg$paths$main_file) else strsplit(main_files, ",")[[1]]
miss <- main_files[!file.exists(main_files)]
if (length(miss)) die("main table not found: %s (set paths.main_file or use --main)",
                      paste(miss, collapse = " | "))
ref_dir <- opt("ref", file.path(here, "..", "ref"))
out_root <- opt("out", from_root(cfg$paths$out))
out_dir <- file.path(out_root, "extract")
dir.create(out_dir, recursive = TRUE, showWarnings = FALSE)
say("main table: %s", paste(basename(main_files), collapse = " | "))
say("output: %s", out_dir)

ex <- cfg$extract
gate_inst <- as.integer(unlist(ex$gate_instances))
groups_sel <- opt("groups")
groups_sel <- if (is.null(groups_sel)) NULL else strsplit(groups_sel, ",")[[1]]
all_groups <- names(ex$groups)
if (!is.null(groups_sel)) {
  bad <- setdiff(groups_sel, all_groups)
  if (length(bad)) die("undefined groups in --groups: %s (available: %s)", paste(bad, collapse = ", "),
                       paste(all_groups, collapse = ", "))
}
run_groups <- if (is.null(groups_sel)) all_groups else groups_sel

# ── 1. Requested fields ───────────────────────────────────────────────
want <- list()
for (g in run_groups) {
  spec <- ex$groups[[g]]
  parts <- list()
  if (!is.null(spec$list)) {
    f <- file.path(ref_dir, spec$list)
    if (!file.exists(f)) die("feature list for group %s not found: %s (run py/build_brain_ref.py)", g, f)
    d <- fread(f, encoding = "UTF-8")
    parts$list <- d[, .(field = as.integer(field), short_name, label, subgroup = modality, required = TRUE)]
  }
  if (!is.null(spec$fields)) {
    f <- spec$fields
    parts$fields <- data.table(field = as.integer(names(f)), short_name = unlist(f), label = unlist(f),
                               subgroup = g, required = TRUE)
  }
  if (!is.null(spec$ranges)) {
    fs <- unlist(lapply(spec$ranges, function(r) seq(as.integer(r[[1]]), as.integer(r[[2]]))))
    parts$ranges <- data.table(field = fs, short_name = paste0("f", fs), label = paste0("field ", fs),
                               subgroup = g, required = FALSE)
  }
  wg <- rbindlist(parts)
  if (!is.null(spec$companions)) {
    rng <- as.integer(unlist(spec$companions$apply_range))
    base <- wg[field >= rng[1] & field <= rng[2]]
    off <- spec$companions$offsets
    comp <- rbindlist(lapply(names(off), function(k)
      base[, .(field = field + as.integer(k), short_name = paste0(short_name, "_", off[[k]]),
               label = paste0(label, " (", off[[k]], ")"), subgroup = paste0(g, ":", off[[k]]), required = TRUE)]))
    wg <- rbind(wg, comp)
  }
  wg <- unique(wg, by = "field")
  insts <- if (identical(spec$instances, "all")) "all" else paste(unlist(spec$instances), collapse = ",")
  want[[g]] <- wg[, .(group = g, field, short_name, label, subgroup, required, insts,
                      naming = spec$naming %||% "short", ord = .I)]
}
want <- rbindlist(want)
say("requested: %s", paste(want[, sprintf("%s %d", group[1], .N), by = group]$V1, collapse = ", "))

# ── 2. Parse headers into (field, instance, array) ───────────────────
parse_header <- function(cols) {
  out <- data.table(col = cols, field = NA_integer_, instance = NA_integer_, array = NA_integer_)
  pats <- list(
    list("^(\\d+)-(\\d+)\\.(\\d+)$",       c(1, 2, 3)),   # ukbconv csv
    list("^f\\.(\\d+)\\.(\\d+)\\.(\\d+)$", c(1, 2, 3)),   # ukbconv r / ukbtools
    list("^p(\\d+)_i(\\d+)_a(\\d+)$",      c(1, 2, 3)),   # RAP
    list("^p(\\d+)_i(\\d+)$",              c(1, 2, 0)),
    list("^p(\\d+)_a(\\d+)$",              c(1, 0, 2)),
    list("^p(\\d+)$",                      c(1, 0, 0)),
    list("_f(\\d+)_(\\d+)_(\\d+)$",        c(1, 2, 3)))   # ukbtools descriptive names
  for (p in pats) {
    todo <- is.na(out$field) & grepl(p[[1]], cols)
    if (!any(todo)) next
    m <- regmatches(cols[todo], regexec(p[[1]], cols[todo]))
    grab <- function(k) if (k == 0) 0L else as.integer(vapply(m, `[`, "", k + 1))
    out[todo, `:=`(field = grab(p[[2]][1]), instance = grab(p[[2]][2]), array = grab(p[[2]][3]))]
  }
  out
}
hdr <- rbindlist(lapply(main_files, function(f) {
  h <- names(fread(f, nrows = 0))
  eid_col <- h[grepl("^(f\\.|participant\\.)?eid$", h)][1]
  if (is.na(eid_col)) die("no eid column in %s (accepted: eid / f.eid / participant.eid)", basename(f))
  p <- parse_header(setdiff(h, eid_col))
  n_bad <- sum(is.na(p$field))
  say("  %s: %d columns, %d parsed%s", basename(f), length(h) - 1, nrow(p) - n_bad,
      if (n_bad) sprintf(" (%d without a field ID, ignored)", n_bad) else "")
  p[!is.na(field)][, `:=`(file = f, eid_col = eid_col)]
}))
hdr <- unique(hdr, by = c("field", "instance", "array"))

# ── 3. Requested fields x header ──────────────────────────────────────
split_insts <- function(r) as.integer(strsplit(r, ",")[[1]])
hit <- merge(want, hdr, by = "field", allow.cartesian = TRUE)
hit <- hit[insts == "all" | vapply(seq_len(.N), function(k)
  insts[k] != "all" && instance[k] %in% split_insts(insts[k]), TRUE)]
hit[, multi_arr := max(c(0L, array)) > 0, by = .(group, field, instance)]
hit[, out_col := fifelse(naming == "rap", sprintf("p%d_i%d_a%d", field, instance, array),
                         paste0(short_name, "_i", instance, fifelse(multi_arr, paste0("_a", array), "")))]
dup <- hit[, .N, by = .(group, out_col)][N > 1]
if (nrow(dup)) die("duplicated output column names (check short names): %s", paste(head(dup$out_col, 5), collapse = ", "))
setorder(hit, group, instance, ord, array)

# Missing fields: required rows only (fields / list / companions), per (field, instance) where instances are listed
wf <- want[required == TRUE & insts != "all"]
ni <- lengths(lapply(wf$insts, split_insts))
exp_fixed <- data.table(wf[rep(seq_len(nrow(wf)), ni), .(group, field, short_name, label)],
                        instance = as.integer(unlist(lapply(wf$insts, split_insts))))
missing <- rbind(
  exp_fixed[!hit, on = .(group, field, instance)],
  want[required == TRUE & insts == "all"][!hit, on = .(group, field)][, .(group, field, short_name, label,
                                                                       instance = NA_integer_)])
keep_other_groups <- function(new, fname) {
  f <- file.path(out_dir, fname)
  if (is.null(groups_sel) || !file.exists(f) || file.size(f) == 0) return(new)
  old <- fread(f)
  if (!"group" %in% names(old)) return(new)
  old <- old[!group %in% groups_sel]
  if (nrow(old)) say("  %s: keeping %d rows of other groups (%s)", fname, nrow(old), paste(unique(old$group), collapse = ", "))
  rbind(old, new, fill = TRUE)
}
fwrite(keep_other_groups(missing, "m_e1_missing.csv"), file.path(out_dir, "m_e1_missing.csv"))
say("%d columns matched; %d requested (field, instance) pairs absent from the main table -> m_e1_missing.csv",
    nrow(hit), nrow(missing))
if (nrow(missing)) print(missing[, .(n_missing = .N), by = .(group, instance)])
rng_hit <- want[required == FALSE, .(n_range = .N), by = group][
  hit[required == FALSE, .(n_hit = uniqueN(field)), by = group], on = "group"]
if (nrow(rng_hit)) for (k in seq_len(nrow(rng_hit)))
  say("  %s: %d of %d field IDs in the ranges are present (ranges contain unused IDs)",
      rng_hit$group[k], rng_hit$n_hit[k], rng_hit$n_range[k])
empty <- setdiff(run_groups, unique(hit$group))
if (length(empty)) die("no column of these groups was found in the main table: %s", paste(empty, collapse = ", "))

# ── 4. Row sets ───────────────────────────────────────────────────────
read_block <- function(f, eid_col, cols, ...) {
  x <- fread(f, select = c(eid_col, cols), na.strings = c("", "NA"), showProgress = FALSE, ...)
  setnames(x, eid_col, "eid")
  x
}
gated <- run_groups[vapply(run_groups, function(g) !isFALSE(ex$groups[[g]]$gate), TRUE)]
wd_file <- opt("withdraw", from_root(cfg$paths$withdraw))
if (isTRUE(wd_file) || !file.exists(wd_file)) {
  warn("withdrawal list not found (paths.withdraw); only negative eids are removed")
  wd <- integer(0)
} else {
  wd <- fread(wd_file, header = FALSE)[[1]]
  say("withdrawal list %s: %d eids", basename(wd_file), length(wd))
}
clean_eids <- function(x, what) {
  x <- as.integer(x)
  x <- x[!is.na(x) & x > 0]
  if (length(wd)) say("  %s: %d withdrawn participants removed", what, sum(x %in% wd))
  sort(setdiff(x, wd))
}
e_all <- unique(unlist(lapply(unique(hdr$file), function(f)
  fread(f, select = hdr[file == f]$eid_col[1], showProgress = FALSE)[[1]])))
e_all <- clean_eids(e_all, "all participants")
say("all participants: %d", length(e_all))
e_gate <- integer(0)
if (length(gated)) {
  gate <- hdr[field == as.integer(ex$gate_field) & instance %in% gate_inst]
  if (!nrow(gate)) die("main table lacks field %s at instance %s (needed by groups with gate: true)",
                       ex$gate_field, paste(gate_inst, collapse = "/"))
  for (f in unique(gate$file)) {
    g <- read_block(f, gate[file == f]$eid_col[1], gate[file == f]$col, colClasses = "character")
    e_gate <- union(e_gate, g$eid[rowSums(!is.na(g[, -1])) > 0])
  }
  e_gate <- clean_eids(e_gate, "imaging cohort")
  say("row gate (%s): %d participants with field %s at instance %s", paste(gated, collapse = ", "),
      length(e_gate), ex$gate_field, paste(gate_inst, collapse = "/"))
}
rows_of <- setNames(lapply(run_groups, function(g) if (g %in% gated) e_gate else e_all), run_groups)

# drop_empty_rows: one pass over the group's columns to find participants with any value
chunk <- as.integer(ex$chunk_cols)
for (g in run_groups[vapply(run_groups, function(g) isTRUE(ex$groups[[g]]$drop_empty_rows), TRUE)]) {
  any_val <- rep(FALSE, length(rows_of[[g]]))
  hg <- hit[group == g]
  for (f in unique(hg$file)) {
    idx <- split(seq_len(sum(hg$file == f)), ceiling(seq_len(sum(hg$file == f)) / chunk))
    cols_f <- hg[file == f]$col
    for (b in seq_along(idx)) {
      x <- read_block(f, hg[file == f]$eid_col[1], cols_f[idx[[b]]], colClasses = "character")
      r <- match(rows_of[[g]], x$eid)
      nn <- Reduce(`|`, lapply(cols_f[idx[[b]]], function(c) !is.na(x[[c]])), FALSE)
      ok <- !is.na(r)
      any_val[ok] <- any_val[ok] | nn[r[ok]]
      rm(x); invisible(gc())
    }
  }
  say("  %s: drop_empty_rows -> %d / %d participants with any value (%s)", g, sum(any_val), length(any_val),
      elapsed())
  rows_of[[g]] <- rows_of[[g]][any_val]
}

# ── 5. Read in column chunks and distribute to groups ─────────────────
res <- setNames(lapply(run_groups, function(g) data.table(eid = rows_of[[g]])), run_groups)
for (f in unique(hit$file)) {
  hf <- unique(hit[file == f], by = "col")
  idx <- split(seq_len(nrow(hf)), ceiling(seq_len(nrow(hf)) / chunk))
  for (b in seq_along(idx)) {
    cols <- hf$col[idx[[b]]]
    x <- read_block(f, hf$eid_col[1], cols)
    hk <- hit[file == f & col %in% cols]
    for (g in unique(hk$group)) {
      hg <- hk[group == g]
      rows <- match(res[[g]]$eid, x$eid)
      res[[g]][, (hg$out_col) := x[rows, hg$col, with = FALSE]]
    }
    say("  %s chunk %d/%d (%d columns) read (%s)", basename(f), b, length(idx), length(cols), elapsed())
    rm(x); invisible(gc())
  }
}

av_list <- list()
for (g in names(res)) {
  h <- hit[group == g]
  setcolorder(res[[g]], c("eid", h$out_col))
  out <- file.path(out_dir, sprintf("m_e1_%s.csv.gz", g))
  fwrite(res[[g]], out)
  say("  %-12s %7d participants x %4d columns -> %s", g, nrow(res[[g]]), ncol(res[[g]]) - 1, basename(out))
  av_list[[g]] <- h[, {
    k <- Reduce(`+`, lapply(out_col, function(c) !is.na(res[[g]][[c]])), 0L)
    .(n_cols = .N, n_any = sum(k > 0), n_complete = sum(k == .N))
  }, by = .(subgroup, instance)][, group := g]
  res[[g]] <- NULL
  invisible(gc())
}
av <- rbindlist(av_list)
setcolorder(av, c("group", "subgroup", "instance"))
print(av)
fwrite(keep_other_groups(av, "m_e1_availability.csv"), file.path(out_dir, "m_e1_availability.csv"))
dict <- hit[, .(group, out_col, field, instance, array, short_name, label, subgroup,
                source_file = basename(file), source_col = col)]
dict <- keep_other_groups(dict, "m_e1_dictionary.csv")
fwrite(dict, file.path(out_dir, "m_e1_dictionary.csv"))
say("done (%s). Dictionary: %d rows (%s) -> m_e1_dictionary.csv", elapsed(), nrow(dict),
    paste(dict[, .N, by = group][, sprintf("%s %d", group, N)], collapse = ", "))
